static bool append_ptyname(char **pp, char *name)
{
	char *p;
	size_t new_len;

	if (!*pp) {
		new_len = strlen(name) + strlen("container_ttys=") + 1;
		if (new_len < strlen(name)) /* overflow check */
			return false;
		*pp = malloc(new_len);
		if (!*pp)
			return false;
		snprintf(*pp, new_len, "container_ttys=%s", name);
		return true;
	}
	new_len = strlen(*pp) + strlen(name) + 2;
	if (new_len < strlen(*pp)) /* overflow check */
		return false;
	p = realloc(*pp, new_len);
	if (!p)
		return false;
	*pp = p;
	strcat(p, " ");
	strcat(p, name);
	return true;
}

int expread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t rdlen, offset;
	off_t mapcnt, mapl, maph, pagestart;

	if (!(client->server->flags & F_COPYONWRITE))
		return(rawexpread_fully(a, buf, len, client));
	DEBUG("Asked to read %u bytes at %llu.\n", (unsigned int)len, (unsigned long long)a);

	mapl=a/DIFFPAGESIZE; maph=(a+len-1)/DIFFPAGESIZE;

	for (mapcnt=mapl;mapcnt<=maph;mapcnt++) {
		pagestart=mapcnt*DIFFPAGESIZE;
		offset=a-pagestart;
		if (offset < 0 || offset >= DIFFPAGESIZE) return -1; /* sanity check */
		rdlen = (len < (size_t)(DIFFPAGESIZE - offset)) ? len : (size_t)(DIFFPAGESIZE - offset);
		if (client->difmap[mapcnt]!=(u32)(-1)) { /* the block is already there */
			DEBUG("Page %llu is at %lu\n", (unsigned long long)mapcnt,
			       (unsigned long)(client->difmap[mapcnt]));
			myseek(client->difffile, client->difmap[mapcnt]*DIFFPAGESIZE+offset);
			if (read(client->difffile, buf, rdlen) != rdlen) return -1;
		} else { /* the block is not there */
			DEBUG("Page %llu is not here, we read the original one\n",
			       (unsigned long long)mapcnt);
			if(rawexpread_fully(a, buf, rdlen, client)) return -1;
		}
		len-=rdlen; a+=rdlen; buf+=rdlen;
	}
	return 0;
}

