void ff_h264_parse_framesize(AVCodecParameters *par, const char *p)
{
    char buf1[50];
    char *dst = buf1;
    const char *sep;

    while (*p && *p == ' ')
        p++;                     // strip spaces.
    while (*p && *p != ' ')
        p++;                     // eat protocol identifier
    while (*p && *p == ' ')
        p++;                     // strip trailing spaces.

    // Find the '-' separator, but do not copy beyond buffer
    sep = p;
    while (*sep && *sep != '-')
        sep++;
    if (*sep != '-')
        return; // or handle error

    // Copy the width part, ensuring null termination
    while (p < sep && (dst - buf1) < sizeof(buf1) - 1)
        *dst++ = *p++;
    *dst = '\0';

    par->width = atoi(buf1);
    par->height = atoi(sep + 1); // skip the '-'
}

