BGD_DECLARE(gdImagePtr) gdImageCreateFromWebpCtx (gdIOCtx * infile)
{
	int    width, height;
	uint8_t   *filedata = NULL;
	uint8_t    *argb = NULL;
	unsigned char   *read, *temp;
	size_t size = 0, n;
	gdImagePtr im;
	int x, y;
	uint8_t *p;

	do {
		temp = gdRealloc(filedata, size+GD_WEBP_ALLOC_STEP);
		if (temp) {
			filedata = temp;
			read = temp + size;
		} else {
			if (filedata) {
				gdFree(filedata);
			}
			gd_error("WebP decode: realloc failed");
			return NULL;
		}

		n = gdGetBuf(read, GD_WEBP_ALLOC_STEP, infile);
		if (n>0 && n!=EOF) {
			size += n;
		}
	} while (n>0 && n!=EOF);

	if (WebPGetInfo(filedata,size, &width, &height) == 0) {
		gd_error("gd-webp cannot get webp info");
		gdFree(temp);
		return NULL;
	}

	im = gdImageCreateTrueColor(width, height);
	if (!im) {
		gdFree(temp);
		return NULL;
	}
	argb = WebPDecodeARGB(filedata, size, &width, &height);
	if (!argb) {
		gd_error("gd-webp cannot allocate temporary buffer");
		gdFree(temp);
		gdImageDestroy(im);
		return NULL;
	}
	/* Ensure the decoded buffer size matches the expected dimensions */
	if ((size_t)width * height > SIZE_MAX / 4) {
		gd_error("gd-webp dimensions overflow");
		free(argb);
		gdFree(temp);
		gdImageDestroy(im);
		return NULL;
	}
	for (y = 0, p = argb;  y < height; y++) {
		for (x = 0; x < width; x++) {
			register uint8_t a = gdAlphaMax - (*(p++) >> 1);
			register uint8_t r = *(p++);
			register uint8_t g = *(p++);
			register uint8_t b = *(p++);
			im->tpixels[y][x] = gdTrueColorAlpha(r, g, b, a);
		}
	}
	/* do not use gdFree here, in case gdFree/alloc is mapped to something else than libc */
	free(argb);
	gdFree(temp);
	im->saveAlphaFlag = 1;
 	return im;
 }

/* replace directory references if path is not a single slash */
if ((flags & PHP_HTTP_URL_SANITIZE_PATH)
&&	url(buf)->path[0] && url(buf)->path[1]) {
	char *ptr, *end = url(buf)->path + strlen(url(buf)->path) + 1;

	for (ptr = strchr(url(buf)->path, '/'); ptr; ptr = strchr(ptr, '/')) {
		switch (ptr[1]) {
			case '/':
				memmove(&ptr[1], &ptr[2], end - &ptr[2]);
				end = url(buf)->path + strlen(url(buf)->path) + 1;
				break;

			case '.':
				switch (ptr[2]) {
					case '\0':
						ptr[1] = '\0';
						end = url(buf)->path + strlen(url(buf)->path) + 1;
						break;

					case '/':
						memmove(&ptr[1], &ptr[3], end - &ptr[3]);
						end = url(buf)->path + strlen(url(buf)->path) + 1;
						break;

					case '.':
						if (ptr[3] == '/') {
							char *pos = &ptr[4];
							while (ptr != url(buf)->path) {
								if (*--ptr == '/') {
									break;
								}
							}
							memmove(&ptr[1], pos, end - pos);
							end = url(buf)->path + strlen(url(buf)->path) + 1;
							break;
						} else if (!ptr[3]) {
							/* .. at the end */
							ptr[1] = '\0';
							end = url(buf)->path + strlen(url(buf)->path) + 1;
						}
						/* no break */

					default:
						/* something else */
						++ptr;
						break;
				}
				break;

			default:
				++ptr;
				break;
		}
	}
}

