buffer_from_file(struct buffer *buffer, FILE *fp)
{
 struct buffer_list *last = &buffer->first;
 size_t count = 0;

 for (;;)
 {
   if (count >= sizeof last->buffer) {
     // сброс или переход к следующему буферу
     count = 0;
     if (last->next == NULL) {
       last = buffer_extend(last);
       if (last == NULL)
         return MEMORY;
     } else {
       last = last->next;
     }
   }
   size_t space = sizeof last->buffer - count;
   size_t r = fread(last->buffer + count, 1, space, fp);

   if (r > 0) {
     count += r;
     if (count >= sizeof last->buffer) {
       // обработка заполнения буфера
       if (count > sizeof last->buffer) {
         // ошибка: fread вернул больше, чем запрошено
         return ERANGE;
       }
       count = 0;
       if (last->next == NULL) {
         last = buffer_extend(last);
         if (last == NULL)
           return MEMORY;
       } else {
         last = last->next;
       }
     }
   } else {
     if (feof(fp)) {
       buffer->last = last;
       buffer->end_count = count;
       return 0;
     }
     return errno == 0 ? ERANGE : errno;
   }
 }
}

