char *path_name(const struct name_path *path, const char *name)
{
    const struct name_path *p;
    char *n, *m;
    size_t nlen = strlen(name);
    size_t len = nlen + 1;

    for (p = path; p; p = p->up) {
        if (p->elem_len)
            len += p->elem_len + 1;
    }
    n = xmalloc(len);
    m = n + len - (nlen + 1);
    memcpy(m, name, nlen);
    m[nlen] = '\0';
    for (p = path; p; p = p->up) {
        if (p->elem_len) {
            m -= p->elem_len + 1;
            memcpy(m, p->elem, p->elem_len);
            m[p->elem_len] = '/';
        }
    }
    return n;
}

construct_command_line(struct manager_ctx *manager, struct server *server)
{
    static char cmd[BUF_SIZE];
    char *method = manager->method;
    int i;
    int len = 0;
    int remaining;

    build_config(working_dir, server);

    if (server->method) method = server->method;
    memset(cmd, 0, BUF_SIZE);
    len = snprintf(cmd, BUF_SIZE,
             "%s -m %s --manager-address %s -f %s/.shadowsocks_%s.pid -c %s/.shadowsocks_%s.conf",
             executable, method, manager->manager_address,
             working_dir, server->port, working_dir, server->port);
    if (len < 0 || len >= BUF_SIZE) {
        // Handle error or truncation
        return NULL;
    }

    #define APPEND_FORMAT(fmt, ...) \
        do { \
            remaining = BUF_SIZE - len; \
            if (remaining <= 0) return NULL; \
            int ret = snprintf(cmd + len, remaining, fmt, ##__VA_ARGS__); \
            if (ret < 0 || ret >= remaining) return NULL; \
            len += ret; \
        } while (0)

    if (manager->acl != NULL) {
        APPEND_FORMAT(" --acl %s", manager->acl);
    }
    if (manager->timeout != NULL) {
        APPEND_FORMAT(" -t %s", manager->timeout);
    }
#ifdef HAVE_SETRLIMIT
    if (manager->nofile) {
        APPEND_FORMAT(" -n %d", manager->nofile);
    }
#endif
    if (manager->user != NULL) {
        APPEND_FORMAT(" -a %s", manager->user);
    }
    if (manager->verbose) {
        APPEND_FORMAT(" -v");
    }
    if (server->mode == NULL && manager->mode == UDP_ONLY) {
        APPEND_FORMAT(" -U");
    }
    if (server->mode == NULL && manager->mode == TCP_AND_UDP) {
        APPEND_FORMAT(" -u");
    }
    if (server->fast_open[0] == 0 && manager->fast_open) {
        APPEND_FORMAT(" --fast-open");
    }
    if (manager->ipv6first) {
        APPEND_FORMAT(" -6");
    }
    if (manager->mtu) {
        APPEND_FORMAT(" --mtu %d", manager->mtu);
    }
    if (server->plugin == NULL && manager->plugin) {
        APPEND_FORMAT(" --plugin \"%s\"", manager->plugin);
    }
    if (server->plugin_opts == NULL && manager->plugin_opts) {
        APPEND_FORMAT(" --plugin-opts \"%s\"", manager->plugin_opts);
    }
    for (i = 0; i < manager->nameserver_num; i++) {
        APPEND_FORMAT(" -d %s", manager->nameservers[i]);
    }
    for (i = 0; i < manager->host_num; i++) {
        APPEND_FORMAT(" -s %s", manager->hosts[i]);
    }
    // Always enable reuse port
    APPEND_FORMAT(" --reuse-port");

    if (verbose) {
        LOGI("cmd: %s", cmd);
    }

    return cmd;
}

